INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Updates und Patch-Management eine technische Maßnahme zur IT-Sicherheit?', 2, '[{"text": "Ja", "correct": true, "because": "Schützen vor Schwachstellen"}, {"text": "Nein", "correct": false, "because": "Sie sind essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgen Updates und Patch-Management?', 3, '[{"text": "Schwachstellen in Software beheben", "correct": true, "because": "Sichert Systeme"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Maßnahme"}, {"text": "Netzwerk trennen", "correct": false, "because": "Keine Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Updates schließen Sicherheitslücken. b) Sie sind nur für Hardware relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch Software"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten umfasst Patch-Management?', 4, '[{"text": "Erkennung von Schwachstellen", "correct": true, "because": "Erster Schritt"}, {"text": "Unklare Prozesse", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Verteilung von Updates", "correct": true, "because": "Behebt Schwachstellen"}, {"text": "Überwachung der Installation", "correct": true, "because": "Sichert Vollständigkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein System ohne Updates sicher sein?', 2, '[{"text": "Nein", "correct": true, "because": "Schwachstellen bleiben"}, {"text": "Ja", "correct": false, "because": "Risiko erhöht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielen Updates im Datenschutz?', 3, '[{"text": "Schutz vor Datenlecks durch Schwachstellen", "correct": true, "because": "Sichert Vertraulichkeit"}, {"text": "Daten löschen", "correct": false, "because": "Keine Funktion"}, {"text": "Identität prüfen", "correct": false, "because": "Authentifizierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Updates nur für Betriebssysteme relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Anwendungen"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat Patch-Management?', 3, '[{"text": "Systematische Aktualisierung von Software", "correct": true, "because": "Schließt Sicherheitslücken"}, {"text": "Netzwerkgeschwindigkeit erhöhen", "correct": false, "because": "Kein Zusammenhang"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Maßnahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Updates verhindern Exploits. b) Sie sind immer optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, oft zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Updates und Patch-Management?', 3, '[{"text": "Systeme bleiben anfällig für Angriffe", "correct": true, "because": "Schwachstellen offen"}, {"text": "Systeme schneller", "correct": false, "because": "Unsinn"}, {"text": "Daten sicherer", "correct": false, "because": "Gegenteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Patch-Management ohne Planung erfolgen?', 2, '[{"text": "Ja", "correct": true, "because": "Aber ineffizient"}, {"text": "Nein", "correct": false, "because": "Planung verbessert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine Maßnahme des Patch-Managements?', 3, '[{"text": "Wöchentliche Update-Installation", "correct": true, "because": "Konkret und real"}, {"text": "Daten löschen", "correct": false, "because": "Keine Maßnahme"}, {"text": "Netzwerk trennen", "correct": false, "because": "Andere Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Patch-Management nur für Software relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Firmware"}, {"text": "Ja", "correct": false, "because": "Breite Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat effektives Patch-Management?', 4, '[{"text": "Regelmäßigkeit", "correct": true, "because": "Aktuelle Sicherheit"}, {"text": "Unklare Prozesse", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Priorisierung", "correct": true, "because": "Wichtige Patches zuerst"}, {"text": "Testphase", "correct": true, "because": "Vermeidet Probleme"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Updates immer sofort installiert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Testen empfohlen"}, {"text": "Ja", "correct": false, "because": "Risiken möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt Patch-Management bei Sicherheitslücken?', 3, '[{"text": "Schließt bekannte Schwachstellen", "correct": true, "because": "Sichert Systeme"}, {"text": "Erhöht Netzwerkgeschwindigkeit", "correct": false, "because": "Kein Zusammenhang"}, {"text": "Identität prüfen", "correct": false, "because": "Authentifizierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein System ohne Updates betrieben werden?', 2, '[{"text": "Ja", "correct": true, "because": "Aber unsicher"}, {"text": "Nein", "correct": false, "because": "Risiko erhöht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinflusst Patch-Management?', 3, '[{"text": "Schweregrad der Schwachstelle", "correct": true, "because": "Bestimmt Dringlichkeit"}, {"text": "Monitorgröße", "correct": false, "because": "Irrelevant"}, {"text": "Tastaturlayout", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Patch-Management schützt vor Exploits. b) Es ist nur für Betriebssysteme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch Anwendungen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen von Updates und Patch-Management?', 3, '[{"text": "Erhöhte Systemsicherheit", "correct": true, "because": "Schließt Schwachstellen"}, {"text": "Maximale Unsicherheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Aktualisierung", "correct": false, "because": "Fördert Schutz"}]');
